// The native fixture supplies immutable object artifacts. These adversarial
// controls mutate serialized metadata at every stage without recompilation.
function runObjectGrammarTests(artifacts,group){
 const results=[];
 for(const [stage,good]of Object.entries(artifacts)){
  const validate=bytes=>groups.validateObject(groups.parseBuffer(bytes),group,stage);
  validate(good);const parsed=groups.parseBuffer(good),nullAt=parsed.header.shoff;
  for(const [label,offset,value]of [
   ['null flags',nullAt+8,1],['null address',nullAt+12,4],['null size',nullAt+20,4],
   ['null alignment',nullAt+32,4]
  ]){const bad=Buffer.from(good);bad.writeUInt32BE(value,offset);assert.throws(()=>validate(bad));validate(good);results.push({stage,label,rejected:true});}
  for(const name of ['.data','.bss']){const section=parsed.sections.find(s=>s.name===name);assert(section);const bad=Buffer.from(good);bad.writeUInt32BE(4,section.headerOffset+20);assert.throws(()=>validate(bad));validate(good);results.push({stage,label:'nonempty '+name,rejected:true});}
 }
 return{status:'pass',negativeControls:results.length,results};
}
module.exports.runObjectGrammarTests=runObjectGrammarTests;


