// unrelated to retail reconstruction and grant no additional game ownership.
function syntheticSource(){return 'extern int synthetic_external(int);\n'
 +'float synthetic_scale(float x) { return x * 1.25 + 2.75; }\n'
 +'int synthetic_dispatch(int x) { switch(x) { case 0: return synthetic_external(7); case 1: return synthetic_external(19); case 2: return synthetic_external(31); case 3: return synthetic_external(43); case 4: return synthetic_external(59); default: return -11; } }\n'
 +'int synthetic_finish(int x) { return x + 13; }\n';}

// Independent reference interpreter for the finite REL types emitted here.
// It uses the untouched native object and chosen synthetic placements, never a
// projected object, projection report, or linked output from the code under test.
function syntheticReference(native,addresses,external){
 const p7=require('../tools/lib/phase7_conventional'),elf=groups.parseBuffer(native);
 const payload=Object.fromEntries(Object.keys(addresses).map(name=>{const s=elf.sections.find(s=>s.name===name);assert(s);return[name,Buffer.from(p7.elfSectionBytes(elf,s))];}));
 const pending=new Map(),operations=[];
 const address=s=>s.sectionIndex===0?external[s.name]:addresses[elf.sections[s.sectionIndex]?.name]+s.value;
 for(const r of groups.relocations(elf)){
  assert(payload[r.owner.name],'unexpected synthetic relocation owner');const bytes=payload[r.owner.name],word=bytes.readUInt32BE(r.place),S=address(r.symbol);assert(Number.isInteger(S));
  const key=r.symbol.symbolTableIndex+':'+r.symbol.symbolIndex;
  if(r.type===5){assert(!pending.has(key));pending.set(key,{r,word});continue;}
  if(r.type===6){const hi=pending.get(key);assert(hi);assert.equal(hi.r.owner.name,r.owner.name);const value=(S+(hi.word&65535)*65536+(word<<16>>16))>>>0;
   bytes.writeUInt32BE(((hi.word&0xffff0000)|(((value+0x8000)>>>16)&65535))>>>0,hi.r.place);bytes.writeUInt32BE(((word&0xffff0000)|(value&65535))>>>0,r.place);pending.delete(key);operations.push({kind:'HI_LO',owner:r.owner.name,hi:hi.r.place,lo:r.place,symbolIndex:r.symbol.symbolIndex,S,value});
  }else if(r.type===4){const value=(S+(word&0x3ffffff)*4)>>>0;assert.equal(value>>>28,(addresses[r.owner.name]+r.place+4)>>>28);bytes.writeUInt32BE(((word&0xfc000000)|((value>>>2)&0x3ffffff))>>>0,r.place);operations.push({kind:'R26',owner:r.owner.name,place:r.place,symbolIndex:r.symbol.symbolIndex,S,value});
  }else if(r.type===2){const value=(S+word)>>>0;bytes.writeUInt32BE(value,r.place);operations.push({kind:'R32',owner:r.owner.name,place:r.place,symbolIndex:r.symbol.symbolIndex,S,addend:word,value});}
  else assert.fail('unsupported synthetic reference relocation '+r.type);
 }
 assert.equal(pending.size,0);return{payload,operations};
}

