 for(const f of others.slice(0,2)){const pc=Array.from({length:f.bytes/4},(_,i)=>f.offset+i*4).find(pc=>!groups.relocations(original).some(r=>r.owner.index===text.index&&r.place===pc));assert(Number.isInteger(pc));assert.throws(()=>check(branch(pc,protectedTarget)),/producer-wide alternate entry/);results.push('outside '+f.symbol+' branch into window');}
 for(const [name,opcode]of [['likely branch',0x50000000],['REGIMM link',0x04110000],['COP1 branch',0x45010000]]){assert.throws(()=>check(branch(others[0].offset,protectedTarget,opcode)),/producer-wide alternate entry/);results.push(name);}
