 for(const [name,to,opcode,symbol]of [['relocated J',protectedTarget,2,anchor],['relocated JAL',protectedTarget,3,anchor],['named symbol plus addend J',protectedTarget,2,named],['relocated terminal-delay J',good.delay,2,anchor]]){assert.throws(()=>check(jump(to,opcode,symbol)),/producer-wide alternate entry/);results.push(name);}
 check(branch(others[0].offset,others[0].offset+8));positives.push('unrelated outside-function branch');check(jump(others[0].offset,2));positives.push('unrelated relocated J');check(jump(others[0].offset,3));positives.push('unrelated relocated JAL');
 const indirect=Buffer.from(native);indirect.writeUInt32BE(0x0040f809,text.offset+others[0].offset);check(indirect);positives.push('unrelated JALR remains permitted');
